var PLUGIN_NAME = "FirebaseMessaging";
// @ts-ignore
var exec = require("cordova/exec");

/**
 *
 * In general (for both platforms) you can only rely on custom data fields.
 *
 * `message_id` and `sent_time` have `google.` prefix in property name (__will be fixed__).
 *
 * @typedef PushPayload
 * @property {Record<string, any>} data Custom data sent from server
 * @property {string} google.message_id Message ID automatically generated by the server
 * @property {number} google.sent_time Time in milliseconds from the Epoch that the message was sent.
 * @property {Record<string, any>} [gcm] Android payload, available ONLY when message arrives in foreground.
 * @property {Record<string, any>} [aps] IOS payload, available when message arrives in both foreground and background.
 */

exports.subscribe =
/**
 *
 * Subscribe to a FCM topic.
 * @param {string} topic Topic name
 * @returns {Promise<void>} Callback when operation is completed
 *
 * @example
 * cordova.plugins.firebase.messaging.subscribe("news");
 */
function(topic) {
    return new Promise(function(resolve, reject) {
        exec(resolve, reject, PLUGIN_NAME, "subscribe", [topic]);
    });
};

exports.unsubscribe =
/**
 *
 * Unsubscribe from a FCM topic.
 * @param {string} topic Topic name
 * @returns {Promise<void>} Callback when operation is completed
 *
 * @example
 * cordova.plugins.firebase.messaging.unsubscribe("news");
 */
function(topic) {
    return new Promise(function(resolve, reject) {
        exec(resolve, reject, PLUGIN_NAME, "unsubscribe", [topic]);
    });
};

exports.onTokenRefresh =
/**
 *
 * Registers callback to notify when FCM token is updated.
 *
 * Use `getToken` to generate a new token.
 * @param {() => void} callback Callback function
 * @param {(error: string) => void} [errorCallback] Error callback function
 *
 * @example
 * cordova.plugins.firebase.messaging.onTokenRefresh(function() {
 *     console.log("Device token updated");
 * });
 */
function(callback, errorCallback) {
    exec(callback, errorCallback, PLUGIN_NAME, "onTokenRefresh", []);
};

exports.onMessage =
/**
 *
 * Registers foreground push notification callback.
 * @param {(payload: PushPayload) => void} callback Callback function
 * @param {(error: string) => void} [errorCallback] Error callback function
 *
 * @example
 * cordova.plugins.firebase.messaging.onMessage(function(payload) {
 *     console.log("New foreground FCM message: ", payload);
 * });
 */
function(callback, errorCallback) {
    exec(callback, errorCallback, PLUGIN_NAME, "onMessage", []);
};

exports.onBackgroundMessage =
/**
 *
 * Registers background push notification callback.
 * @param {(payload: PushPayload) => void} callback Callback function
 * @param {(error: string) => void} [errorCallback] Error callback function
 *
 * @example
 * cordova.plugins.firebase.messaging.onBackgroundMessage(function(payload) {
 *     console.log("New background FCM message: ", payload);
 * });
 */
function(callback, errorCallback) {
    exec(callback, errorCallback, PLUGIN_NAME, "onBackgroundMessage", []);
};

/**
 * Event name triggered when a new Firebase Cloud Messaging (FCM) or push notification token is generated.
 * @constant
 * @type {string}
 */
exports.TOKEN_REFRESH_EVENT = 'onTokenRefresh';

/**
 * Event name triggered when a new push notification or message is received while the application is in the foreground.
 * @constant
 * @type {string}
 */
exports.MESSAGE_EVENT = 'onMessage';

/**
 * Event name triggered when a data message or push notification is received while the application is in the background or terminated.
 * @constant
 * @type {string}
 */
exports.BACKGROUND_MESSAGE_EVENT = 'onBackgroundMessage';

exports.on =
/**
 * Creates an asynchronous iterable stream (Async Generator) for a specific native Cordova event.
 * Uses the Web Streams API under the hood to safely manage backpressure, queuing, and memory cleanup.
 *
 * @example
 * const firebaseMessaging = cordova.plugins.firebase.messaging;
 * const controller = new AbortController();
 *
 * async function listenTokenRefresh() {
 *   try {
 *     const fcmMessageStream = firebaseMessaging.on(firebaseMessaging.MESSAGE_EVENT, controller.signal);
 *     for await (const message of fcmMessageStream) {
 *       console.log('Received message from FCM:', message);
 *     }
 *   } catch (error) {
 *     console.error('Stream encountered an error:', error);
 *   }
 * }
 *
 * // To stop listening and clean up native resources later:
 * // controller.abort();
 *
 * @param {string} eventName - The name of the native event/action to listen to.
 * @param {AbortSignal} [signal] - An optional AbortSignal instance to trigger unsubscription and release resources.
 * @returns {AsyncGenerator<any, void, unknown>} An async generator that yields data chunks sent from the native layer.
 */
async function* (eventName, signal) {
    if (signal?.aborted) return;

    let streamController;

    const stream = new ReadableStream({
        start(controller) {
            streamController = controller;

            exec(
                (data) => {
                    if (controller.desiredSize !== null) {
                        controller.enqueue(data);
                    }
                },
                (error) => {
                    if (controller.desiredSize !== null) {
                        controller.error(new Error(error));
                    }
                },
                PLUGIN_NAME,
                eventName,
                []
            );
        },
        cancel() {
            exec(null, null, PLUGIN_NAME, eventName, []);
        }
    });

    const cleanup = () => {
        if (streamController.desiredSize !== null) {
            reader.cancel().catch(() => {});
        }
    };

    signal?.addEventListener('abort', cleanup, { once: true });

    const reader = stream.getReader();
    try {
        while (true) {
            const { value, done } = await reader.read();
            if (done) break;
            yield value;
        }
    } finally {
        signal?.removeEventListener('abort', cleanup);
        cleanup();
        reader.releaseLock();
    }
};

async function* createEventStream(eventName, signal) {
    if (signal?.aborted) return;

    let nativeCallbackRegistered = true;

    const unsubscribe = () => new Promise((resolve, reject) => {
        if (nativeCallbackRegistered) {
            nativeCallbackRegistered = false;
            exec(resolve, reject, PLUGIN_NAME, "off" + eventName, []);
        } else {
            resolve();
        }
    });

    const stream = new ReadableStream({
        start(controller) {
            exec(
                (data) => {
                    if (nativeCallbackRegistered && controller.desiredSize !== null) {
                        controller.enqueue(data);
                    }
                },
                (error) => {
                    if (nativeCallbackRegistered && controller.desiredSize !== null) {
                        controller.error(new Error(error));
                    }
                },
                PLUGIN_NAME,
                "on" + eventName,
                []
            );
        },
        cancel: unsubscribe
    });

    const reader = stream.getReader();
    const cleanup = () => reader.cancel().catch(() => {});

    signal?.addEventListener('abort', cleanup, { once: true });

    try {
        while (true) {
            const { value, done } = await reader.read();
            if (done) break;
            yield value;
        }
    } finally {
        signal?.removeEventListener('abort', cleanup);
        await unsubscribe().catch(() => {});
        reader.releaseLock();
    }
}

exports.streamTokenRefresh =
/**
 * Subscribes to the FCM token refresh event stream.
 *
 * @example
 * const controller = new AbortController();
 * for await (const token of FirebaseMessaging.streamTokenRefresh(controller.signal)) {
 *     console.log("New FCM Token arrived:", token);
 * }
 *
 * @param {AbortSignal} [signal] - An optional signal to abort the stream.
 * @returns {AsyncGenerator<string, void, unknown>} An async generator yielding refreshed token strings.
 */
function (signal) {
    return createEventStream('TokenRefresh', signal);
}

exports.streamMessage =
/**
 * Subscribes to the stream of incoming push notifications received while the app is in the foreground.
 *
 * @example
 * const controller = new AbortController();
 * for await (const message of FirebaseMessaging.streamMessage(controller.signal)) {
 *     console.log("Received a foreground push notification:", message);
 * }
 *
 * @param {AbortSignal} [signal] - An optional signal to abort the stream.
 * @returns {AsyncGenerator<PushPayload, void, unknown>} An async generator yielding message payloads.
 */
function(signal) {
    return createEventStream('Message', signal);
}

exports.streamBackgroundMessage =
/**
 * Subscribes to the stream of incoming push notifications received while the app is in the background.
 *
 * @example
 * const controller = new AbortController();
 * for await (const message of FirebaseMessaging.streamBackgroundMessage(controller.signal)) {
 *     console.log("Received a background push notification:", message);
 * }
 *
 * @param {AbortSignal} [signal] - An optional signal to abort the stream.
 * @returns {AsyncGenerator<PushPayload, void, unknown>} An async generator yielding message payloads.
 */
function(signal) {
    return createEventStream('BackgroundMessage', signal);
}

exports.clearNotifications =
/**
 *
 * Clear all notifications from system notification bar.
 * @returns {Promise<void>} Callback when operation is completed
 *
 * @example
 * cordova.plugins.firebase.messaging.clearNotifications();
 */
function() {
    return new Promise(function(resolve, reject) {
        exec(resolve, reject, PLUGIN_NAME, "clearNotifications", []);
    });
};

exports.deleteToken =
/**
 *
 * Delete the Instance ID (Token) and the data associated with it.
 *
 * Call getToken to generate a new one.
 * @returns {Promise<void>} Callback when operation is completed
 *
 * @example
 * cordova.plugins.firebase.messaging.deleteToken();
 */
function() {
    return new Promise(function(resolve, reject) {
        exec(resolve, reject, PLUGIN_NAME, "deleteToken", []);
    });
};

exports.getToken =
/**
 *
 * Returns the current FCM token.
 * @param {"apns-buffer" | "apns-string"} [format] Token representation (iOS only)
 * @returns {Promise<string>} Promise fulfiled with the current FCM token
 *
 * @example
 * cordova.plugins.firebase.messaging.getToken().then(function(token) {
 *     console.log("Got device token: ", token);
 * });
 */
function(format) {
    return new Promise(function(resolve, reject) {
        exec(resolve, reject, PLUGIN_NAME, "getToken", [format || ""]);
    });
};

exports.setBadge =
/**
 *
 * Sets current badge number (if supported).
 * @param {number} badgeValue New badge value
 * @returns {Promise<void>} Callback when operation is completed
 *
 * @example
 * cordova.plugins.firebase.messaging.setBadge(value);
 */
function(badgeValue) {
    return new Promise(function(resolve, reject) {
        exec(resolve, reject, PLUGIN_NAME, "setBadge", [badgeValue]);
    });
};

exports.getBadge =
/**
 *
 * Gets current badge number (if supported).
 * @returns {Promise<number>} Promise fulfiled with the current badge value
 *
 * @example
 * cordova.plugins.firebase.messaging.getBadge().then(function(value) {
 *     console.log("Badge value: ", value);
 * });
 */
function() {
    return new Promise(function(resolve, reject) {
        exec(resolve, reject, PLUGIN_NAME, "getBadge", []);
    });
};

exports.requestPermission =
/**
 *
 * Ask for permission to recieve push notifications (will trigger prompt on iOS).
 * @param {object} options Additional options.
 * @param {boolean} options.forceShow When value is `true` incoming notification is displayed even when app is in foreground.
 * @returns {Promise<void>} Filfiled promise when permission is granted.
 *
 * @example
 * cordova.plugins.firebase.messaging.requestPermission({forceShow: false}).then(function() {
 *     console.log("Push messaging is allowed");
 * });
 */
function(options) {
    return new Promise(function(resolve, reject) {
        if (options) {
            if (typeof options.forceShow !== "boolean" && typeof options.forceShow !== "undefined") {
                return reject(new TypeError("forceShow option must be a boolean"));
            }
        }

        exec(resolve, reject, PLUGIN_NAME, "requestPermission", [options || {}]);
    });
};
